from __future__ import annotations

import os
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from senpy.analyzer import SenpyAnalyzer


def generate_project_wiki(analyzer: SenpyAnalyzer) -> str:
    """Генерирует Markdown-документацию (Wiki) по проекту на основе AST и символов."""
    lines: list[str] = [
        "# Project Documentation (Generated by Senpy)",
        "",
        "> This document was automatically generated from Ren'Py source scripts.",
        "",
    ]

    # 1. Персонажи (Characters)
    lines.append("## Characters")
    lines.append("")
    if analyzer.declared_characters:
        lines.append("| Identifier | Declaration Source |")
        lines.append("| :--- | :--- |")
        for char in sorted(analyzer.declared_characters):
            src_file = "Unknown"
            src_line = "?"
            if char in analyzer.symbol_declarations:
                fpath, lnum, _ = analyzer.symbol_declarations[char]
                src_file = os.path.basename(fpath)
                src_line = str(lnum)
            lines.append(f"| `{char}` | `{src_file}:{src_line}` |")
    else:
        lines.append("_No Character declarations detected._")
    lines.append("")

    # 2. Переменные и состояние (default / define)
    lines.append("## State & Variables")
    lines.append("")
    if analyzer.symbol_declarations:
        lines.append("| Variable | Type | Kind | Source |")
        lines.append("| :--- | :--- | :--- | :--- |")
        for var, (fpath, lnum, _) in sorted(analyzer.symbol_declarations.items()):
            if var in analyzer.declared_characters:
                continue
            is_const = var in analyzer.defined_constants
            kind = "Constant (`define`)" if is_const else "Variable (`default`)"
            var_type = analyzer.symbol_types.get(var, "unknown")
            fname = os.path.basename(fpath)
            lines.append(f"| `{var}` | `{var_type}` | {kind} | `{fname}:{lnum}` |")
    else:
        lines.append("_No variables or constants detected._")
    lines.append("")

    # 3. Сюжетные концовки (Endings)
    lines.append("## Story Endings")
    lines.append("")
    # Концовки — это метки с return, из которых нет исходящих jump
    endings = []
    for lbl in sorted(analyzer.declared_labels.keys()):
        if lbl.startswith("_"):
            continue
        has_return = lbl in analyzer.labels_with_return
        has_outgoing = len(analyzer.label_outgoing_jumps.get(lbl, set())) > 0
        if has_return and not has_outgoing:
            fpath, lnum, _ = analyzer.declared_labels[lbl]
            endings.append((lbl, os.path.basename(fpath), lnum))

    if endings:
        lines.append("| Ending Label | Source Location |")
        lines.append("| :--- | :--- |")
        for lbl, fname, lnum in endings:
            lines.append(f"| `{lbl}` | `{fname}:{lnum}` |")
    else:
        lines.append("_No explicit terminal endings detected._")
    lines.append("")

    return "\n".join(lines)